export interface ImageAsset {
  /** Basename in /public/images, generated by `npm run images`. */
  name: string;
  width: number;
  height: number;
  alt: string;
}

export interface Outcome {
  value: string;
  label: string;
}

/** An interactive demo or diagram shown alongside a highlight. */
export type Visual = "realtime-demo" | "worker-demo" | "query-diagram";

export interface ProductArea {
  name: string;
  description: string;
}

export interface Highlight {
  title: string;
  body: string[];
  visual?: Visual;
  /** One or two sentences introducing the visual. */
  visualNote?: string;
}

export interface CaseStudy {
  slug: string;
  company: string;
  companyUrl: string;
  role: string;
  period: string;
  location: string;
  /** One line describing the product. */
  product: string;
  /** Headline for the case study page and the home page card. */
  title: string;
  /** Two sentences for the home page card and metadata. */
  summary: string;
  /** The product, and the scope of my work on it. */
  overview: string[];
  /** Parts of the product I worked across. */
  areas: ProductArea[];
  outcomes: Outcome[];
  /** The engineering work worth telling in detail. */
  highlights: Highlight[];
  /** How I worked with the team: process, quality, collaboration. */
  practices: string[];
  decisions: { title: string; body: string }[];
  impact: string;
  stack: string[];
  image: ImageAsset;
  /** Panel colour behind the screenshot, taken from the product's branding. */
  tint: string;
}

export interface Role {
  company: string;
  title: string;
  period: string;
  location: string;
  summary: string;
  caseStudy?: string;
}
